import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineVat, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[0].qty, 3);
  assert.equal(result.value.lines[0].unitPrice, 8500);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-06-30',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[1].name, 'Icon set (24 icons)');
  assert.equal(result.value.lines[2].name, 'Brand workshop (day, VAT exempt)');
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('createInvoice rejects unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  const cases = [
    '2025/01/15',
    '15-01-2025',
    '2025-1-15',
    '2025-01-5',
    '01-15-2025',
    'invalid',
    '2025-02-30',
    '2024-02-30',
    '',
    null,
    undefined,
  ];
  for (const dateStr of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' }, `should reject ${JSON.stringify(dateStr)}`);
  }
});

test('createInvoice accepts valid dates including leap years', () => {
  const validDates = ['2024-02-29', '2025-01-01', '2099-12-31', '1970-01-01'];
  for (const dateStr of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, true, `should accept ${dateStr}`);
  }
});

test('createInvoice rejects missing lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [],
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects non-array lines', () => {
  const cases = [undefined, null, {}, 'lines', 123];
  for (const lines of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines,
    });
    assert.deepEqual(result, { ok: false, error: 'NO_LINES' }, `should reject ${JSON.stringify(lines)}`);
  }
});

test('createInvoice rejects invalid quantities', () => {
  const invalidQtys = [0, -1, -5, 0.5, 1.5, 3.14, 'three', null, undefined, {}, []];
  for (const qty of invalidQtys) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' }, `should reject qty ${JSON.stringify(qty)}`);
  }
});

test('createInvoice rejects unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'UNKNOWN', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice returns early on first error', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: 'invalid',
    lines: [{ sku: 'UNKNOWN', qty: 0 }],
  });
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice does not mutate arguments', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const linesCopy = JSON.stringify(lines);
  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines,
  });
  assert.equal(JSON.stringify(lines), linesCopy);
});

test('createInvoice returns copies of lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  result.value.lines[0].name = 'MODIFIED';
  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result2.value.lines[0].name, 'Design work (hour)');
});

test('createInvoice normalizes customer ID to uppercase', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID by trimming spaces', () => {
  const result = createInvoice({
    customerId: 'C-001 ',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with mixed case and spaces', () => {
  const result = createInvoice({
    customerId: ' c-003 ',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice finds customer with unnormalized ID', () => {
  const result = createInvoice({
    customerId: 'c-007 ',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-007');
});

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 3, unitPrice: 8500 }), 25500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 50 }), 500);
});

test('lineTotal handles single unit', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
});

test('lineTotal handles zero price', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 0 }), 0);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 2, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 3 * 8500 + 2 * 9500);
  assert.equal(totals.subtotal, 44500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, Math.round(44500 * 0.21));
  assert.equal(totals.total, 44500 + totals.vat);
});

test('invoiceTotals handles single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [{ sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 25200);
  assert.equal(totals.total, 145200);
});

test('invoiceTotals handles multiple items with varying quantities', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 5, unitPrice: 980, vatRate: 21, discountPercent: 0 },
      { sku: 'STICKER', name: 'Sticker sheet', qty: 100, unitPrice: 50, vatRate: 21, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 2, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 980 + 100 * 50 + 2 * 60000);
  assert.equal(totals.subtotal, 129900);
  assert.equal(totals.discount, 0);
  const vatableAmount = 5 * 980 + 100 * 50;
  const vat = Math.round(vatableAmount * 0.21);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 129900 + vat);
});

test('invoiceTotals does not mutate the invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21 }],
  };
  const invoiceCopy = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), invoiceCopy);
});

test('addLine adds a new line to the invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
});

test('addLine rejects invalid qty', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: -1 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'UNKNOWN', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine rejects modification of non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const invoiceCopy = JSON.stringify(invoice);

  addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(JSON.stringify(invoice), invoiceCopy);
});

test('removeLine removes a line from the invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 1 },
    ],
